package com.mybank.pbac.controller;
import com.mybank.pbac.dto.PolicyTargetRequest; import com.mybank.pbac.model.PolicyTarget; import com.mybank.pbac.service.PolicyTargetService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/policy-targets") public class PolicyTargetController{private final PolicyTargetService s;public PolicyTargetController(PolicyTargetService s){this.s=s;}@GetMapping public List<PolicyTarget> all(){return s.all();}@PostMapping public PolicyTarget add(@Valid @RequestBody PolicyTargetRequest r){return s.save(null,r);}@PutMapping("/{id}") public PolicyTarget edit(@PathVariable Long id,@Valid @RequestBody PolicyTargetRequest r){return s.save(id,r);}@DeleteMapping("/{id}") public void delete(@PathVariable Long id){s.delete(id);}}
